metro.set_edge_attrs("on_route", {e: 0 for e in metro.get_edge_ids()})
metro.set_edge_attrs("on_route", 1, edges=list(legs))
metro.plot(
    layout="pos", edge_color_by="route", edge_width_by="on_route",
